#include <stdio.h>

int search(int *ptr, int n, int x) {
    for (int i = 0; i < n; i++) {
        if (*(ptr + i) == x) return i;
    }
    return -1;
}

int main() {
    int a[] = {7, 3, 9, 4};
    printf("%d\n", search(a, 4, 9));
    printf("%d\n", search(a, 4, 5));
    return 0;
}
